mapper.sql:
WITH objRec AS( SELECT tmp3.REG_CODE, tmp3.VDATE, tmp3.hodeDate, tmp3.RAISE_QTY, tmp3.TOTAL_AMT FROM ( SELECT tmp2.REG_CODE, tmp2.VDATE, tmp2.hodeDate, B.RAISE_QTY, B.TOTAL_AMT, ROW_NUMBER() over( partition by tmp2.REG_CODE ORDER BY B.STATUS DESC ,B.UPDATE_TIME DESC) AS raiseStatusNo FROM ( SELECT A.REG_CODE, A.VDATE, #{searchDate,jdbcType=DATE} AS hodeDate FROM CHB_PRD_BASEINFO A LEFT JOIN ( SELECT PROD_REGIST_CODE, MAX(MDATE) FROM CHB_PRD_DEAL_SUB WHERE STATUS IN ('01','02') AND MDATE <= #{searchDate,jdbcType=DATE} GROUP BY PROD_REGIST_CODE ) tmp1 ON A.REG_CODE = tmp1.PROD_REGIST_CODE WHERE tmp1.PROD_REGIST_CODE = null
#{orgCode,jdbcType=VARCHAR}
) tmp2 INNER JOIN CHB_PRD_RAISETOT_SUB B ON (tmp2.REG_CODE = B.PROD_REGIST_CODE AND STATUS IN ('01','02')) ) tmp3 WHERE raiseStatusNo = 1 )
